<!--
 * 规则引擎实时监控看板（新页面）
 *
 * @path apps/literule-web/src/views/dashboard/index.vue
 * @author ydsz-team
 * @since 4.2.0
-->
<script lang="ts" setup>
/**
 * 规则引擎实时监控看板
 * <p>消费后端契约 RuleDashboardController（src/api/ruleDashboard.ts，auto-generated by bash/gen-contract.py）：
 * overview / trends / distribution / top-rules / realtime / slow-rules / hot-rules 全量端点：
 * 首屏概览指标卡 + 趋势折线 + 状态分布饼图 + Top 规则 / 热点 / 慢规则列表，30s 自动刷新。
 * 图表基于 @ydsz/plugins/echarts（EchartsUI + useEcharts），列表基于 vxe-grid（useYDSZVxeGrid）。
 *
 * @author ydsz-team
 * @since 4.2.0
 */
import type { ECOption, EchartsUIType } from '@ydsz/plugins/echarts';
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { EchartsUI, useEcharts } from '@ydsz/plugins/echarts';

import { Page } from '@ydsz/common-ui';

import { ElCard, ElCol, ElRow, ElStatistic } from 'element-plus';
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import type {
  RuleDashboardDistributionVO,
  RuleDashboardOverviewVO,
  RuleDashboardRealtimeVO,
  RuleDashboardTopRuleVO,
  RuleDashboardTrendVO,
} from '#/api/models';
import { distribution, hotRules, overview, realtime, slowRules, topRules, trends } from '#/api/ruleDashboard';

defineOptions({ name: 'RuleDashboard' });

/** 数据快照（7 个端点并行拉取） */
const loading = ref(false);
const overviewData = ref<RuleDashboardOverviewVO | null>(null);
const realtimeData = ref<RuleDashboardRealtimeVO | null>(null);
const trendData = ref<RuleDashboardTrendVO | null>(null);
const distributionData = ref<RuleDashboardDistributionVO | null>(null);
const hotRuleList = ref<Record<string, unknown>[]>([]);
const slowRuleList = ref<Record<string, unknown>[]>([]);
const topRuleList = ref<RuleDashboardTopRuleVO[]>([]);

/** 综合取整（避免 undefined 参与计算） */
function num(value: number | undefined | null): number {
  return Number(value ?? 0);
}

/** 0~1 比率转百分比文案 */
function ratioText(value: number | undefined | null): string {
  return `${(num(value) * 100).toFixed(1)}%`;
}

/**
 * 从 distribution.statusPie（{name,value}[]）抽取饼图数据。
 * <p>分布接口字段为 Record<string, unknown>[] 的弱类型契约，防御性取值并过滤 0 值扇区。
 */
function toPieData(list: Record<string, unknown>[] | undefined): { name: string; value: number }[] {
  return (list ?? [])
    .map((item) => ({ name: String(item?.name ?? '未知'), value: Number(item?.value ?? 0) }))
    .filter((item) => item.value > 0);
}

/** 趋势折线图配置（评估/命中/异常 3 条序列） */
const trendOption = computed<ECOption>(() => ({
  backgroundColor: 'transparent',
  tooltip: { trigger: 'axis' },
  legend: { bottom: 0, data: ['评估次数', '命中次数', '异常次数'] },
  grid: { left: 8, right: 16, top: 36, bottom: 32, containLabel: true },
  xAxis: { type: 'category', boundaryGap: false, data: trendData.value?.timeLabels ?? [] },
  yAxis: { type: 'value' },
  series: [
    {
      name: '评估次数',
      type: 'line',
      smooth: true,
      showSymbol: false,
      data: trendData.value?.evaluationSeries ?? [],
      itemStyle: { color: '#409eff' },
    },
    {
      name: '命中次数',
      type: 'line',
      smooth: true,
      showSymbol: false,
      data: trendData.value?.triggeredSeries ?? [],
      itemStyle: { color: '#67c23a' },
    },
    {
      name: '异常次数',
      type: 'line',
      smooth: true,
      showSymbol: false,
      data: trendData.value?.errorSeries ?? [],
      itemStyle: { color: '#f56c6c' },
    },
  ],
}));

/** 状态分布饼图配置 */
const pieOption = computed<ECOption>(() => ({
  backgroundColor: 'transparent',
  tooltip: { trigger: 'item' },
  legend: { bottom: 0, type: 'scroll' },
  series: [
    {
      name: '规则状态分布',
      type: 'pie',
      radius: ['38%', '64%'],
      center: ['50%', '44%'],
      avoidLabelOverlap: true,
      label: { show: true, formatter: '{b}: {c}' },
      data: toPieData(distributionData.value?.statusPie),
    },
  ],
}));

const trendChartRef = ref<EchartsUIType>();
const { renderEcharts: renderTrendChart } = useEcharts(trendChartRef);

const pieChartRef = ref<EchartsUIType>();
const { renderEcharts: renderPieChart } = useEcharts(pieChartRef);

watch(
  trendOption,
  (option) => {
    void renderTrendChart(option);
  },
  { deep: true, immediate: true },
);

watch(
  pieOption,
  (option) => {
    void renderPieChart(option);
  },
  { deep: true, immediate: true },
);

/** Top 规则（按触发次数倒序） */
const topGridOptions: VxeTableGridOptions<RuleDashboardTopRuleVO> = {
  columns: [
    { type: 'seq', width: 48, title: '#' },
    { field: 'ruleCode', title: '规则编码', width: 130 },
    { field: 'ruleName', title: '规则名称', minWidth: 120 },
    { field: 'category', title: '分类', width: 90 },
    { field: 'evaluations', title: '评估次数', width: 90 },
    { field: 'triggered', title: '命中次数', width: 90 },
    {
      field: 'triggerRate',
      title: '命中率',
      width: 90,
      slots: {
        default: ({ row }) => (row.triggerRate == null ? '-' : ratioText(row.triggerRate)),
      },
    },
  ],
  height: 280,
  proxyConfig: {
    ajax: {
      query: async () => ({ items: topRuleList.value, total: topRuleList.value.length }),
    },
  },
};

/** 热点规则（引擎内建指标） */
const hotGridOptions: VxeTableGridOptions<Record<string, unknown>> = {
  columns: [
    { type: 'seq', width: 48, title: '#' },
    { field: 'ruleCode', title: '规则编码', width: 150 },
    { field: 'evaluations', title: '评估次数', width: 100 },
    { field: 'triggered', title: '命中次数', width: 100 },
    { field: 'avgMs', title: '平均耗时(ms)', width: 110 },
    { field: 'p99Ms', title: 'P99耗时(ms)', width: 110 },
  ],
  height: 280,
  proxyConfig: {
    ajax: {
      query: async () => ({ items: hotRuleList.value, total: hotRuleList.value.length }),
    },
  },
};

/** 慢规则（引擎内建指标） */
const slowGridOptions: VxeTableGridOptions<Record<string, unknown>> = {
  columns: [
    { type: 'seq', width: 48, title: '#' },
    { field: 'ruleCode', title: '规则编码', width: 150 },
    { field: 'evaluations', title: '评估次数', width: 100 },
    { field: 'avgMs', title: '平均耗时(ms)', width: 110 },
    { field: 'maxMs', title: '最大耗时(ms)', width: 110 },
    { field: 'p99Ms', title: 'P99耗时(ms)', width: 110 },
  ],
  height: 280,
  proxyConfig: {
    ajax: {
      query: async () => ({ items: slowRuleList.value, total: slowRuleList.value.length }),
    },
  },
};

const [TopGrid] = useYDSZVxeGrid({ gridOptions: topGridOptions });
const [HotGrid] = useYDSZVxeGrid({ gridOptions: hotGridOptions });
const [SlowGrid] = useYDSZVxeGrid({ gridOptions: slowGridOptions });

/** 并行拉取全部看板数据 */
async function loadDashboard(): Promise<void> {
  loading.value = true;
  try {
    const [ov, rt, tr, dist, top, hot, slow] = await Promise.all([
      overview(),
      realtime(),
      trends({}),
      distribution(),
      topRules({ type: 'triggered', limit: 10 }),
      hotRules({ limit: 10 }),
      slowRules({ limit: 10 }),
    ]);
    overviewData.value = ov;
    realtimeData.value = rt;
    trendData.value = tr;
    distributionData.value = dist;
    topRuleList.value = Array.isArray(top) ? top : [];
    hotRuleList.value = Array.isArray(hot) ? hot : [];
    slowRuleList.value = Array.isArray(slow) ? slow : [];
  } catch {
    // 错误提示由请求拦截器统一处理，指标保持最近一次快照
  } finally {
    loading.value = false;
  }
}

let refreshTimer: ReturnType<typeof setInterval> | null = null;

onMounted(() => {
  void loadDashboard();
  refreshTimer = setInterval(() => {
    void loadDashboard();
  }, 30_000);
});

onBeforeUnmount(() => {
  if (refreshTimer) clearInterval(refreshTimer);
  refreshTimer = null;
});
</script>
<template>
  <Page auto-content-height>
    <div v-loading="loading" class="p-4">
      <!-- 概览指标卡 -->
      <ElRow :gutter="12" class="mb-4">
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="规则总数" :value="num(overviewData?.totalRules)" />
          </ElCard>
        </ElCol>
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="已启用" :value="num(overviewData?.enabledRules)" />
          </ElCard>
        </ElCol>
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="今日评估" :value="num(overviewData?.todayEvaluations)" />
          </ElCard>
        </ElCol>
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="今日命中" :value="num(overviewData?.todayTriggered)" />
          </ElCard>
        </ElCol>
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="今日触发率" :value="ratioText(overviewData?.todayTriggerRate)" />
          </ElCard>
        </ElCol>
        <ElCol :span="4">
          <ElCard shadow="never">
            <ElStatistic title="今日异常" :value="num(overviewData?.todayErrors)" />
          </ElCard>
        </ElCol>
      </ElRow>
      <!-- 实时指标带 -->
      <ElRow :gutter="12" class="mb-4">
        <ElCol
          v-for="item in [
            { label: '实时QPS', value: realtimeData?.currentQps },
            { label: '注册规则', value: realtimeData?.registeredRules },
            { label: '活跃规则', value: realtimeData?.activeRules },
            { label: '近段评估', value: realtimeData?.recentEvaluations },
            { label: '近段命中', value: realtimeData?.recentTriggered },
            { label: '近段异常', value: realtimeData?.recentErrors },
          ]"
          :key="item.label"
          :span="4"
        >
          <ElCard shadow="never">
            <ElStatistic :title="item.label" :value="item.value == null ? '-' : String(item.value)" />
          </ElCard>
        </ElCol>
      </ElRow>
      <!-- 趋势 + 分布 -->
      <ElRow :gutter="12" class="mb-4">
        <ElCol :span="16">
          <ElCard shadow="never" header="规则评估趋势（近24h）">
            <EchartsUI ref="trendChartRef" height="320px" />
          </ElCard>
        </ElCol>
        <ElCol :span="8">
          <ElCard shadow="never" header="规则状态分布">
            <EchartsUI ref="pieChartRef" height="320px" />
          </ElCard>
        </ElCol>
      </ElRow>
      <!-- Top 规则 + 热点/慢规则 -->
      <ElRow :gutter="12">
        <ElCol :span="8">
          <ElCard shadow="never" header="Top 规则（按命中）" class="h-full">
            <TopGrid />
          </ElCard>
        </ElCol>
        <ElCol :span="8">
          <ElCard shadow="never" header="热点规则" class="h-full">
            <HotGrid />
          </ElCard>
        </ElCol>
        <ElCol :span="8">
          <ElCard shadow="never" header="慢规则" class="h-full">
            <SlowGrid />
          </ElCard>
        </ElCol>
      </ElRow>
    </div>
  </Page>
</template>